import React, { useState, useRef, useEffect, useCallback } from 'react';
import { attendanceAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectionIntervalRef = useRef(null);
  const detectionTimeoutRef = useRef(null);
  const isProcessingRef = useRef(false); // Verrou pour éviter d'envoyer 50 requêtes en même temps

  // ============ STATE ============
  const [cameraActive, setCameraActive] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  // ============ GESTION CAMÉRA ============
  const startCamera = async () => {
    try {
      setError(null);
      setLoading(true);

      const constraints = {
        video: {
          facingMode: 'user',
          width: { ideal: 1280 },
          height: { ideal: 720 },
          frameRate: { ideal: 30 }
        },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setCameraActive(true);
        if (addNotification) addNotification('✅ Caméra activée', 'success');
      }
    } catch (err) {
      console.error('Erreur caméra:', err);
      setError('Accès caméra refusé ou non disponible.');
    } finally {
      setLoading(false);
    }
  };

  const stopCamera = useCallback(() => {
    if (detectionIntervalRef.current) clearInterval(detectionIntervalRef.current);
    if (detectionTimeoutRef.current) clearTimeout(detectionTimeoutRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setDetecting(false);
    setDetectionProgress(0);
  }, []);

  useEffect(() => {
    return () => stopCamera();
  }, [stopCamera]);

  // ============ LOGIQUE DE CAPTURE HAUTE QUALITÉ ============
  const getFrameBase64 = () => {
    if (!videoRef.current) return null;

    const canvas = document.createElement('canvas');
    // On utilise les dimensions réelles du flux vidéo
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    const ctx = canvas.getContext('2d');

    // Inverser horizontalement pour compenser l'effet miroir de l'UI si nécessaire
    // Ici on capture l'image brute pour le backend
    ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);

    // Qualité 0.95 pour éviter les artefacts de compression qui gênent l'IA
    return canvas.toDataURL('image/jpeg', 0.95);
  };

  // ============ RECONNAISSANCE AUTOMATIQUE (10s) ============
  const startDetection = async () => {
    if (!videoRef.current || detecting) return;

    setDetecting(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setError(null);
    isProcessingRef.current = false;

    let bestMatch = null;
    const startTime = Date.now();
    const DURATION = 10000;

    // Analyse toutes les 800ms (laisser le temps au backend de répondre)
    detectionIntervalRef.current = setInterval(async () => {
      if (isProcessingRef.current) return; // Ne pas surcharger si la requête précédente n'est pas finie

      const image = getFrameBase64();
      if (!image) return;

      try {
        isProcessingRef.current = true;
        const response = await attendanceAPI.recognize(image);
        const data = response?.data;

        if (data && data.success && data.student) {
          // Si on trouve un match avec une confiance suffisante
          if (!bestMatch || data.confidence > bestMatch.confidence) {
            bestMatch = { ...data, photo: image };
          }

          // Si le score est excellent (> 80%), on arrête tout de suite pour gagner du temps
          if (data.confidence > 0.80) {
            finishDetection(bestMatch);
          }
        }
      } catch (err) {
        console.warn("Échec d'une frame, on continue...");
      } finally {
        isProcessingRef.current = false;
      }
    }, 800);

    // Barre de progression
    const progTimer = setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(100, (elapsed / DURATION) * 100);
      setDetectionProgress(progress);
      if (progress >= 100) clearInterval(progTimer);
    }, 100);

    // Timeout final
    detectionTimeoutRef.current = setTimeout(() => {
      finishDetection(bestMatch);
    }, DURATION);
  };

  const finishDetection = (match) => {
    clearInterval(detectionIntervalRef.current);
    clearTimeout(detectionTimeoutRef.current);
    setDetecting(false);

    if (match) {
      setCapturedPhoto(match.photo);
      setMatchResult({
        name: match.student,
        email: match.email || 'Non renseigné',
        confidence: (match.confidence * 100).toFixed(1),
        attendanceId: match.attendance_id,
        timestamp: new Date().toLocaleTimeString()
      });
      if (addNotification) addNotification(`✅ ${match.student} identifié`, 'success');
    } else {
      setError("❌ Aucun visage reconnu. Essayez de mieux vous éclairer.");
    }
  };

  // ============ CAPTURE UNIQUE (MANUELLE) ============
  const captureOnce = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setError(null);
    const image = getFrameBase64();

    try {
      const response = await attendanceAPI.recognize(image);
      const data = response?.data;

      if (data && data.success && data.student) {
        setCapturedPhoto(image);
        setMatchResult({
          name: data.student,
          email: data.email || 'N/A',
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: new Date().toLocaleTimeString()
        });
      } else {
        setError(`❌ Reconnaissance échouée : ${data?.message || 'Visage non identifié'}`);
      }
    } catch (err) {
      setError("❌ Erreur de connexion au serveur de reconnaissance.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>Identification Biométrique</h1>
        <p style={styles.subtitle}>Placez-vous face à la caméra dans un endroit éclairé</p>
      </div>

      <div style={styles.mainZone}>
        {cameraActive ? (
          <div style={styles.cameraWrapper}>
            <video 
              ref={videoRef} 
              autoPlay 
              playsInline 
              muted 
              style={styles.video} 
            />
            {/* Overlay Scan */}
            {detecting && <div style={styles.scanOverlay} />}

            <div style={{
              ...styles.badge,
              backgroundColor: detecting ? COLORS.warning : COLORS.success
            }}>
              {detecting ? 'ANALYSE EN COURS...' : 'CAMÉRA PRÊTE'}
            </div>

            {detecting && (
              <div style={styles.progressContainer}>
                <div style={{ ...styles.progressFill, width: `${detectionProgress}%` }} />
              </div>
            )}
          </div>
        ) : (
          <div style={styles.offlineBox}>
            <div style={{ fontSize: '50px', marginBottom: '20px' }}>📷</div>
            <button onClick={startCamera} style={styles.startBtn}>
              {loading ? 'Chargement...' : 'Activer la Caméra'}
            </button>
          </div>
        )}
      </div>

      {cameraActive && !matchResult && (
        <div style={styles.actionGrid}>
          <button 
            disabled={detecting} 
            onClick={startDetection} 
            style={{ ...styles.btn, background: COLORS.primary }}
          >
            🔍 Détection Auto (10s)
          </button>
          <button 
            disabled={detecting} 
            onClick={captureOnce} 
            style={{ ...styles.btn, background: COLORS.success }}
          >
            📸 Capture Unique
          </button>
          <button onClick={stopCamera} style={{ ...styles.btn, background: COLORS.danger }}>
            🛑 Éteindre
          </button>
        </div>
      )}

      {error && <div style={styles.errorBanner}>{error}</div>}

      {matchResult && (
        <div style={styles.resultCard}>
          <div style={styles.resultHeader}>
            <span style={styles.checkIcon}>✅</span>
            <h2>Identification Réussie</h2>
          </div>

          <div style={styles.resultBody}>
            <div style={styles.resultPhotos}>
              <div style={styles.photoBox}>
                <p style={styles.photoLabel}>Capture Live</p>
                <img src={capturedPhoto} alt="Live" style={styles.imgResult} />
              </div>
              <div style={styles.photoBox}>
                <p style={styles.photoLabel}>Base de données</p>
                <div style={styles.placeholderImg}>👤</div>
              </div>
            </div>

            <div style={styles.infoTable}>
              <InfoRow label="Étudiant" value={matchResult.name} />
              <InfoRow label="Confiance" value={`${matchResult.confidence}%`} highlight />
              <InfoRow label="Heure" value={matchResult.timestamp} />
              <InfoRow label="ID Session" value={matchResult.attendanceId} />
            </div>
          </div>

          <button onClick={() => setMatchResult(null)} style={styles.retryBtn}>
            Nouvelle Identification
          </button>
        </div>
      )}
    </div>
  );
};

